local ADDON, FO = ...
local U = FO.Util

-- ===========================================================================
-- Client-data seed. Data\Items.lua (generated by scripts/build_seed.py from the
-- Forever client's own ItemSparse/Item tables) gives every item a name, vendor
-- sell/buy price, quality, class and level before the player has ever seen it.
-- Util's item helpers fall back to this when the client's item cache is cold.
-- Live data always wins: a GetItemInfo answer or an observed vendor price
-- overrides the seed.
-- ===========================================================================
FO.Seed = FO.Seed or { items = {}, itemCount = 0, build = "none" }
local Seed = FO.Seed

local INVTYPE = {
    [1] = "INVTYPE_HEAD", [2] = "INVTYPE_NECK", [3] = "INVTYPE_SHOULDER", [4] = "INVTYPE_BODY", [5] = "INVTYPE_CHEST",
    [6] = "INVTYPE_WAIST", [7] = "INVTYPE_LEGS", [8] = "INVTYPE_FEET", [9] = "INVTYPE_WRIST", [10] = "INVTYPE_HAND",
    [11] = "INVTYPE_FINGER", [12] = "INVTYPE_TRINKET", [13] = "INVTYPE_WEAPON", [14] = "INVTYPE_SHIELD", [15] = "INVTYPE_RANGED",
    [16] = "INVTYPE_CLOAK", [17] = "INVTYPE_2HWEAPON", [18] = "INVTYPE_BAG", [19] = "INVTYPE_TABARD", [20] = "INVTYPE_ROBE",
    [21] = "INVTYPE_WEAPONMAINHAND", [22] = "INVTYPE_WEAPONOFFHAND", [23] = "INVTYPE_HOLDABLE", [24] = "INVTYPE_AMMO",
    [25] = "INVTYPE_THROWN", [26] = "INVTYPE_RANGEDRIGHT", [27] = "INVTYPE_QUIVER", [28] = "INVTYPE_RELIC",
}

-- Same return shape as U.ItemInfo: name, quality, sell, classID, subclassID, stack, bind, link(nil), equipLoc, ilvl, reqLevel
function Seed.Info(itemID)
    local r = itemID and Seed.items[itemID]
    if not r then return nil end
    return r[1], r[4], r[2], r[8], r[9], r[7], r[10], nil, INVTYPE[r[11]] or "", r[5], r[6]
end

function Seed.VendorBuy(itemID)
    local r = itemID and Seed.items[itemID]
    if r and r[3] > 0 then return r[3] end
    return nil
end

function Seed.StartsQuest(itemID)
    local r = itemID and Seed.items[itemID]
    return r and r[12] or nil
end

-- Case-insensitive name search; returns up to `limit` ids
local lowerIndex
function Seed.Find(text, limit)
    text = (text or ""):lower()
    if text == "" then return {} end
    if not lowerIndex then
        lowerIndex = {}
        for id, r in pairs(Seed.items) do lowerIndex[id] = r[1]:lower() end
    end
    local hits = {}
    for id, lname in pairs(lowerIndex) do
        if lname == text then table.insert(hits, 1, id) elseif lname:find(text, 1, true) then hits[#hits + 1] = id end
        if #hits >= (limit or 10) * 3 then break end
    end
    local n = {}
    for i = 1, math.min(limit or 10, #hits) do n[i] = hits[i] end
    return n
end

FO:RegisterCommand("seed", function(arg)
    arg = U.Str(arg) or ""
    if arg == "" then
        FO:Print("Core", "item seed: %d items from %s build %s. /fo seed <id|name> to look one up.", Seed.itemCount or 0, Seed.product or "?", Seed.build or "?")
        return
    end
    local ids = tonumber(arg) and { tonumber(arg) } or Seed.Find(arg, 8)
    if #ids == 0 then FO:Print("Core", "no seed item matches '%s'", arg) return end
    for _, id in ipairs(ids) do
        local r = Seed.items[id]
        if r then
            FO:Print("Core", "  %d %s  q%d ilvl%d req%d  sell %s  buy %s  stack %d  class %d/%d%s",
                id, r[1], r[4], r[5], r[6], U.FormatMoney(r[2]), r[3] > 0 and U.FormatMoney(r[3]) or "-", r[7], r[8], r[9],
                r[12] and (" starts quest " .. r[12]) or "")
        else
            FO:Print("Core", "  %d not in seed", id)
        end
    end
end, "Client item seed: info, or look up <id|name>")
